// Package tlsutil generates and inspects self-signed server certificates.
package tlsutil

import (
	"bytes"
	"crypto/ecdsa"
	"crypto/elliptic"
	"crypto/rand"
	"crypto/tls"
	"crypto/x509"
	"crypto/x509/pkix"
	"encoding/pem"
	"math/big"
	"time"
)

// Organization marks certificates generated by this package.
const Organization = "xdatabase-proxy"

// SelfSigned returns a PEM encoded self-signed ECDSA P-256 certificate and key valid for one year.
func SelfSigned() (certPEM, keyPEM []byte, err error) {
	key, err := ecdsa.GenerateKey(elliptic.P256(), rand.Reader)
	if err != nil {
		return nil, nil, err
	}
	serial, err := rand.Int(rand.Reader, new(big.Int).Lsh(big.NewInt(1), 127))
	if err != nil {
		return nil, nil, err
	}
	now := time.Now()
	tpl := &x509.Certificate{
		SerialNumber:          serial,
		Subject:               pkix.Name{Organization: []string{Organization}},
		DNSNames:              []string{"localhost"},
		NotBefore:             now.Add(-time.Minute),
		NotAfter:              now.AddDate(1, 0, 0),
		KeyUsage:              x509.KeyUsageDigitalSignature,
		ExtKeyUsage:           []x509.ExtKeyUsage{x509.ExtKeyUsageServerAuth},
		BasicConstraintsValid: true,
	}
	der, err := x509.CreateCertificate(rand.Reader, tpl, tpl, &key.PublicKey, key)
	if err != nil {
		return nil, nil, err
	}
	keyDER, err := x509.MarshalPKCS8PrivateKey(key)
	if err != nil {
		return nil, nil, err
	}
	return pem.EncodeToMemory(&pem.Block{Type: "CERTIFICATE", Bytes: der}),
		pem.EncodeToMemory(&pem.Block{Type: "PRIVATE KEY", Bytes: keyDER}), nil
}

// IsOwnSelfSigned reports whether cert was produced by SelfSigned.
func IsOwnSelfSigned(cert *tls.Certificate) bool {
	leaf := leafOf(cert)
	return leaf != nil && len(leaf.Subject.Organization) == 1 && leaf.Subject.Organization[0] == Organization &&
		bytes.Equal(leaf.RawIssuer, leaf.RawSubject)
}

// ExpiresWithin reports whether cert expires within d (or cannot be parsed).
func ExpiresWithin(cert *tls.Certificate, d time.Duration) bool {
	leaf := leafOf(cert)
	return leaf == nil || time.Now().Add(d).After(leaf.NotAfter)
}

func leafOf(cert *tls.Certificate) *x509.Certificate {
	if cert.Leaf != nil {
		return cert.Leaf
	}
	if len(cert.Certificate) == 0 {
		return nil
	}
	leaf, _ := x509.ParseCertificate(cert.Certificate[0])
	return leaf
}
